using System;
using System.Collections;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "CrimsonEquinoxEffect", menuName = "Data/Battle/Effects/Enemy/CrimsonEquinox Effect")]
public class CrimsonEquinoxEffect : Effect
{
	[Header("State Two Effect")]
	[SerializeField]
	private SingularityGoddessEffect singularityGoddessEffect;

	[Header("VFX")]
	[SerializeField]
	private float delayToDiceActivation;

	[SerializeField]
	private float delayToVFXSpawn;

	[NonSerialized]
	private bool alreadyActivated;

	[NonSerialized]
	private int startingAmount;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		if (LanguagesIndexes.IsCurrentLanguageGerman())
		{
			return base.GetEffectDescription(amount, effectOwner);
		}
		return Smart.Format(GetLocalizedDescription(), base.localizationManager.GetLocalizedEffectOwnerReceiveFormatted(purify: true, startingAmount).RemoveLast());
	}

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		alreadyActivated = false;
		startingAmount = effectAmount;
	}

	public override int ActivateEffectWithPurifyAmountAndSource(int effectAmount, GameObject effectOwner, int purifyAmount, GameObject source)
	{
		if (alreadyActivated)
		{
			return effectAmount;
		}
		int num = effectAmount - purifyAmount;
		UnitEffects unitEffects = effectOwner.GetComponent<UnitEffects>();
		if (num <= 0)
		{
			alreadyActivated = true;
			unitEffects.IsEffectActiveAndDecreaseEffect(this, purifyAmount, activateFeedback: true, removeOnZero: false);
			ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.SetAfterCrimsomEquinoxDiceActivationAction(AfterCrimsomEquinoxDiceActivationCoroutine());
			if (effectOwner.GetComponent<CorruptedAnimalActivation>().IsBoosted)
			{
				ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(DiceActivation(effectOwner, basic: true));
				ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(DiceActivation(effectOwner, basic: false));
			}
			else
			{
				ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(DiceActivation(effectOwner, basic: true));
			}
			ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
		}
		else
		{
			unitEffects.IsEffectActiveAndDecreaseEffect(this, purifyAmount);
		}
		return effectAmount;
		IEnumerator AfterCrimsomEquinoxDiceActivationCoroutine()
		{
			yield return InvokeAlternatives.WaitForFrames(3);
			if (!singularityGoddessEffect.StateOne && !singularityGoddessEffect.ChangingAstreaState)
			{
				unitEffects.RemoveEffect(this, activateFeedback: false);
				unitEffects.AddEffect(this, startingAmount, effectFeedback: true, callEffectsCallbacks: false);
			}
			alreadyActivated = false;
		}
	}

	private IEnumerator DiceActivation(GameObject effectOwner, bool basic)
	{
		CorruptedAnimalActivation ca = effectOwner.GetComponent<CorruptedAnimalActivation>();
		yield return new WaitForSeconds(IsVFXEnabled() ? 0.5f : 0.2f);
		effectOwner.GetComponent<UnitEffects>().IsEffectActive(this);
		if (IsVFXEnabled())
		{
			yield return new WaitForSeconds(delayToVFXSpawn);
			SpawnVFX(GetVFXOwnerPosition(effectOwner), 5f);
			PlayEffectActivationSFX();
			yield return new WaitForSeconds(delayToDiceActivation);
		}
		if (basic)
		{
			yield return ca.BasicDiceActivation();
		}
		else
		{
			yield return ca.BoostDiceActivation();
		}
		yield return new WaitForSeconds(0.3f);
	}
}
